// Byte-exact checks against vectors generated by the Python prototype that
// works on a real Band 9 (proto/tools/make_dart_vectors.py).
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:openwear/protocol/command.dart';
import 'package:openwear/protocol/crypto.dart';
import 'package:openwear/protocol/l1.dart';
import 'package:openwear/protocol/pb.dart';
import 'package:openwear/protocol/session_auth.dart';

Uint8List unhex(String s) => Uint8List.fromList([
  for (var i = 0; i < s.length; i += 2)
    int.parse(s.substring(i, i + 2), radix: 16),
]);
String hex(List<int> b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

void main() {
  final v = jsonDecode(
    File('test/fixtures/vectors.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final key = Uint8List.fromList(List.generate(16, (i) => i));

  test('CRC16-ARC matches', () {
    final c = v['crc16'] as Map<String, dynamic>;
    expect(crc16Arc(unhex(c['input'] as String)), c['crc']);
  });

  test('L1 frames encode identically and read back', () {
    final frame = Frame(
      frameData,
      7,
      Uint8List.fromList([1, 2, ...utf8.encode('hello')]),
    );
    expect(hex(frame.encode()), v['frame']);
    expect(hex(startRequest().encode()), v['start_request']);
    final reader = FrameReader();
    final bytes = frame.encode();
    expect(reader.feed(bytes.sublist(0, 5)), isEmpty);
    final read = reader.feed(bytes.sublist(5)).single;
    expect(
      (read.type, read.seq, hex(read.payload)),
      (frameData, 7, hex(frame.payload)),
    );
  });

  test('protobuf encoding matches every field kind', () {
    final encoded = pbEncode([
      const PbVarint(1, 300),
      const PbString(2, 'hi'),
      const PbBool(3, true),
      const PbSint(4, -3),
      const PbFloat(5, 34.0),
      const PbVarint(6, -1),
      PbBytes(
        7,
        pbEncode([
          PbBytes(1, Uint8List.fromList([0xff])),
        ]),
      ),
    ]);
    expect(hex(encoded), v['pb']);
    final msg = PbMessage.decode(encoded);
    expect((msg.int_(1), msg.string(2)), (300, 'hi'));
    expect(msg.message(7)?.bytes(1), [0xff]);
  });

  test('crypto primitives match', () {
    expect(hex(hmacSha256(key, utf8.encode('message'))), v['hmac']);
    expect(
      hex(hkdfSha256('miwear-auth', key, utf8.encode('salt' * 8), 64)),
      v['hkdf'],
    );
    final sealed = ccmEncrypt(
      key,
      Uint8List(12),
      utf8.encode('companion data'),
      utf8.encode('bind-data'),
    );
    expect(hex(sealed), v['ccm']);
    expect(
      utf8.decode(
        ccmDecrypt(key, Uint8List(12), sealed, utf8.encode('bind-data')),
      ),
      'companion data',
    );
    final data = utf8.encode('counter mode test data, longer than one block');
    expect(hex(aesCtr(key, data)), v['ctr']);
    expect(aesCtr(key, aesCtr(key, data)), data);
  });

  test('command envelope round-trips', () {
    final cmd = Command.of(8, 4, [
      PbBytes(3, Uint8List.fromList(List.filled(7, 1))),
    ]);
    expect(hex(cmd.encode()), v['command']);
    final back = Command.decode(cmd.encode());
    expect(
      (back.type, back.subtype, hex(back.payload!)),
      (8, 4, hex(cmd.payload!)),
    );
  });

  test(
    'session auth produces the same verify and confirm as the prototype',
    () {
      final a = v['auth'] as Map<String, dynamic>;
      final auth = SessionAuth(unhex(a['key'] as String));
      expect(
        hex(auth.verify(unhex(a['app_random'] as String)).encode()),
        a['verify'],
      );
      final confirm = auth.onVerifyResponse(
        Command.decode(unhex(a['verify_rsp'] as String)),
      );
      expect(hex(confirm.encode()), a['confirm']);
    },
  );

  test('session auth rejects a band signed with another key', () {
    final a = v['auth'] as Map<String, dynamic>;
    final auth = SessionAuth(Uint8List(16))
      ..verify(unhex(a['app_random'] as String));
    expect(
      () => auth.onVerifyResponse(
        Command.decode(unhex(a['verify_rsp'] as String)),
      ),
      throwsA(isA<HandshakeException>()),
    );
  });
}
